"La Bella y la Bestia": "Beauty and the Beast",
"La Marea Negra tiñó su cuerpo, haciéndole creer que ya se había muerto": "The Black Tide stained its body, making it believe it had already died",
"La acentuación": "Accent marks",
"La circunferencia es una línea curva cerrada en la que todos los puntos equidistan del centro. Estudia sus partes.": "A circle is a closed curved line in which all points are equally distant from the center. Study its parts.",
"La división como reparto.": "Division as sharing.",
"La escuela. Haz clic en la flecha.": "The school. Click on the arrow.",
"La gaviota fue salvada, por aquella gente que a ella tan poco le gustaba": "The seagull was saved by those people she had never liked very much",
"La habichuela cayó como un árbol derribado por un leñador y el gigante se estrelló contra el suelo. Jack y su madre vivieron felices gracias al oro del gigante.": "The beanstalk fell like a tree cut down by a woodcutter, and the giant crashed to the ground. Jack and his mother lived happily ever after thanks to the giant's gold.",
"La manzana que tiene una hoja está entre la verde y la amarilla. La manzana roja está a la izquierda de la verde. Hay una manzana de color naranja": "The apple that has one leaf is between the green and the yellow one. The red apple is to the left of the green one. There is an orange apple.",
"La manzana roja y la amarilla tienen una hoja cada una.. La manzana roja está a la derecha de la verde": "The red and yellow apples each have one leaf. The red apple is to the right of the green one.",
"La mariquita azul tiene menos puntos que la roja. La flor que tiene más pétalos es amarilla": "The blue ladybug has fewer spots than the red one. The flower that has the most petals is yellow.",
"La mariquita que tiene más puntos es azul. La que tiene menos puntos es amarilla. La roja tiene menos puntos que la verde.": "The ladybug with the most spots is blue. The one with the fewest spots is yellow. The red one has fewer spots than the green one.",
"La mariquita roja tiene cuatro puntos negros. La verde tiene dos puntos mas que la roja. La azul tiene un punto menos que la verde.": "The red ladybug has four black spots. The green one has two more spots than the red one. The blue one has one spot fewer than the green one.",
"La mariquita roja tiene seis puntos. La verde tiene tantos como la azul": "The red ladybug has six spots. The green one has as many as the blue one.",
"La prueba de la división": "Checking division",
"La seta azul tiene dos puntos más que la verde. La seta que más puntos tiene es amarilla": "The blue mushroom has two more spots than the green one. The mushroom with the most spots is yellow.",
"La seta azul tiene más puntos que la roja. La seta verde tiene más puntos que la azul. La rama que tiene menos hojas es amarilla.": "The blue mushroom has more spots than the red one. The green mushroom has more spots than the blue one. The branch with the fewest leaves is yellow.",
"La seta roja tiene cuatro puntos negros. La seta verde tiene dos puntos menos que la roja. La otra seta es azul.": "The red mushroom has four black spots. The green mushroom has two fewer spots than the red one. The other mushroom is blue.",
"La seta verde tiene más puntos que la roja La otra seta es azul. La flor que tiene menos pétalos es amarilla": "The green mushroom has more spots than the red one. The other mushroom is blue. The flower with the fewest petals is yellow.",
