"Jack llego primero y corrió hacia la granja para coger una hacha con la que cortar la habichuela.": "Jack got there first and ran to the farm to grab an axe to chop the beanstalk.",
"Jack y su madre vivían en una pequeña granja y eran muy pobres. La madre decidió vender la vaca que tenían.": "Jack and his mother lived on a small farm and were very poor. The mother decided to sell the cow they had.",
