"Pasó un perro. -Ratita, ratita, ¿te querrías casar conmigo? -A ver, ¿cómo es tu voz? -¡Guau, guau! - ladró el perro. -¡Ay no, no, no me gusta tu ronca voz!": "A dog walked by. -Little mouse, little mouse, would you like to marry me? -Let's see, what's your voice like? -Woof, woof! barked the dog. -Oh no, no, no, I don't like your raspy voice!",
