"Y pasa un gato muy pulido y atusado. -Ratita, ratita, ¿te querrías casar conmigo? -¡A ver, ¿cómo es tu voz? -¡Miau, miaaauu...! -maulló el gato. -¡Ay, sí, sí que me gusta tu fina voz!": "A well-groomed, sleek cat passes by. \"Little mouse, little mouse, would you like to marry me?\" \"Let's see, what is your voice like?\" \"Meow, meeeow...!\" meowed the cat. \"Oh, yes, yes, I love your fine voice!\"",
"Y pasó un cerdo. - Ratita, ratita, ¿te querrías casar conmigo? -A ver, ¿cómo es tu voz? -Gruny, gruny! -gruñó el cerdo. -¡Ay no, no me gusta esta voz!": "A pig passes by. \"Little mouse, little mouse, would you like to marry me?\" \"Let's see, what is your voice like?\" \"Oink, oink!\" grunted the pig. \"Oh no, I don't like this voice!\"",
